    local ok, asset = pcall(function()
        encoded = encoded:gsub("%s+", "")
        local alphabet, values = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", {}
        for i = 1, #alphabet do values[alphabet:byte(i)] = i - 1 end
        local chunks, bytes = {}, {}
        for i = 1, #encoded, 4 do
            local a, b, c, d = encoded:byte(i, i + 3)
            local number = values[a] * 262144 + values[b] * 4096 + (values[c] or 0) * 64 + (values[d] or 0)
            local block = string.char(math.floor(number / 65536) % 256)
            if c ~= 61 then block = block .. string.char(math.floor(number / 256) % 256) end
            if d ~= 61 then block = block .. string.char(number % 256) end
            bytes[#bytes + 1] = block
            if #bytes >= 512 then chunks[#chunks + 1] = table.concat(bytes); bytes = {} end
        end
        chunks[#chunks + 1] = table.concat(bytes)
        local path = "VD_Tegrrr_Blue_v05.png"
        diskWrite(path, table.concat(chunks))
        return customAsset(path)
    end)
    return ok and type(asset) == "string" and asset or ""
end
