local function animate(object, properties)
    extraUI.tweens = extraUI.tweens or setmetatable({}, {__mode = "k"})
    local previous = extraUI.tweens[object]
    if previous then previous:Cancel() end
    if not state.animations or state.lite then
        for key, value in pairs(properties) do object[key] = value end
        return
    end
    local ok, tween = pcall(function()
        return TweenService:Create(object, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), properties)
    end)
    if ok then extraUI.tweens[object] = tween; tween:Play()
    else for key, value in pairs(properties) do object[key] = value end end
end
