    local fpsText = metric("VD_LiveFPS", 10, 66, "FPS --", colors.text)
    local pingText = metric("VD_LivePing", 88, 78, "PING -- ms", Color3.fromRGB(163, 218, 255))
    local frames, elapsed = 0, 0
    RunService:BindToRenderStep(performanceRenderName, Enum.RenderPriority.Last.Value + 1, function(dt)
        if not state.alive then return end
        -- No config flag, menu visibility or authorization check controls this HUD.
        performanceGui.Enabled, glass.Visible = true, true
        if not finite(dt) or dt <= 0 then return end
        frames, elapsed = frames + 1, elapsed + dt
        if elapsed < 0.25 then return end
        fpsText.Text = string.format("FPS %.0f", frames / elapsed)
        frames, elapsed = 0, 0
        -- GetNetworkPing returns real round-trip network latency in seconds.
        -- Poll the native measurement; do not send extra network requests.
        local ok, seconds = pcall(function() return LocalPlayer:GetNetworkPing() end)
        pingText.Text = ok and finite(seconds) and seconds >= 0
            and string.format("PING %.0f ms", seconds * 1000) or "PING -- ms"
    end)
end
