extraUI.layoutMenu = function()
    local surface = surfaceSize()
    -- Keep text readable: shorten the scrolling area instead of fitting a tall phone panel.
    local fit = math.min(1.35, math.max(0.2, (surface.X - 24) / 500), math.max(0.2, (surface.Y - 24) / 170))
    scale.Scale = math.min(state.uiScale, fit)
    extraUI.menuWidth = math.min(700, math.max(240, (surface.X - 24) / scale.Scale))
    extraUI.menuHeight = math.min(380, extraUI.menuWidth / 1.65, math.max(170, (surface.Y - 52) / scale.Scale))
    local width, height = extraUI.menuWidth, extraUI.menuHeight
    panel.Size = UDim2.fromOffset(width, height)
    local position = panel.Position
    local x = math.clamp(position.X.Offset, 0, math.max(0, surface.X - width * scale.Scale))
    local y = math.clamp(position.Y.Offset, 0, math.max(0, surface.Y - height * scale.Scale))
    if x ~= position.X.Offset or y ~= position.Y.Offset then panel.Position = UDim2.fromOffset(x, y) end
end
