    desc.TextWrapped, desc.TextTruncate = false, Enum.TextTruncate.AtEnd
    local control = make("TextButton", row, {Name = "VD_Toggle_" .. key, Size = UDim2.fromOffset(58, 32),
        Position = UDim2.new(1, -70, 0, 8), TextSize = 14, Font = Enum.Font.GothamBold,
        TextColor3 = colors.muted, BorderSizePixel = 0, BackgroundColor3 = colors.edge})
    round(control, 12)
    local lastState
    local function update()
        control.Text = available == false and "N/A" or (state[key] and "ON" or "OFF")
        if lastState ~= state[key] then
            animate(control, {BackgroundColor3 = state[key] and colors.accent or colors.edge,
                TextColor3 = state[key] and colors.base or colors.text})
            lastState = state[key]
        end
        control.AutoButtonColor = available ~= false
    end
    table.insert(updaters, update)
    connect(control.Activated, function()
        if available == false then notify("Your executor does not support this feature."); return end
        setSetting(key, not state[key])
    end)
    update()
    return control
end
