local function characterPart(character, preferred)
    if not character then return nil end
    local names
    if preferred == "Torso" then names = {"UpperTorso", "Torso", "HumanoidRootPart"}
    elseif preferred == "Leg" then names = {"LeftLowerLeg", "RightLowerLeg", "LeftUpperLeg", "RightUpperLeg", "Left Leg", "Right Leg"}
    else names = {preferred or "Head"} end
    for _, name in ipairs(names) do
        local part = character:FindFirstChild(name)
        if part and part:IsA("BasePart") then return part end
    end
    for _, name in ipairs({"HumanoidRootPart", "Head", "UpperTorso", "Torso"}) do
        local part = character:FindFirstChild(name)
        if part and part:IsA("BasePart") then return part end
    end
    return character.PrimaryPart or character:FindFirstChildWhichIsA("BasePart", true)
end
do
    local adapter = extraUI.adapter
    adapter.tag = function(object, tag)
        if not object then return false end
        local ok, tagged = pcall(function() return CollectionService:HasTag(object, tag) end)
        return ok and tagged == true
    end
    adapter.attribute = function(object, key)
        if not object then return nil end
        local ok, value = pcall(function() return object:GetAttribute(key) end)
        return ok and value or nil
    end
    adapter.role = function(player)
        if not player then return "Unknown" end
        local name = player.Team and string.lower(player.Team.Name or tostring(player.Team)) or ""
        if name == "spectator" or name == "lobby" then return "Inactive" end
        if name == "killer" or name == "the killer" or adapter.tag(player.Character, "Killer") then return "Killer" end
        if name == "survivor" or name == "survivors" or adapter.tag(player.Character, "Survivor") then return "Survivor" end
        for _, object in ipairs({player.Character or player, player}) do
            for _, key in ipairs({"Role", "PlayerRole"}) do
                local role = adapter.attribute(object, key)
                if type(role) == "string" then
                    role = string.lower(role)
                    if role == "killer" then return "Killer" end
                    if role == "survivor" then return "Survivor" end
                    if role == "lobby" or role == "spectator" then return "Inactive" end
                end
            end
        end
        -- In the confirmed VD universe, the reference classifies other active teams as survivors.
        if game.GameId == 6739698191 and player.Team and player.Character then return "Survivor" end
        return "Unknown"
    end
    adapter.condition = function(character)
        for _, key in ipairs({"Knocked", "Downed", "IsKnocked"}) do
            if adapter.attribute(character, key) == true then return "Knocked" end
        end
        for _, key in ipairs({"HookProgressDepleting", "Hooked", "IsHooked"}) do
            if adapter.attribute(character, key) == true then return "Hooked" end
        end
        for _, key in ipairs({"Carried", "IsCarried"}) do
            if adapter.attribute(character, key) == true then return "Carried" end
        end
        if adapter.attribute(character, "Bleeding") == true or adapter.attribute(character, "IsBleeding") == true then return "Injured" end
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if humanoid and finite(humanoid.MaxHealth) and humanoid.Health < humanoid.MaxHealth then return "Injured" end
        return "Alive"
    end
    adapter.canRepair = function()
        local character = LocalPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local role = adapter.role(LocalPlayer)
        if not humanoid or humanoid.Health <= 0 or role == "Killer" or role == "Inactive"
            or adapter.attribute(character, "Dead") == true then return false end
        local condition = adapter.condition(character)
        return condition == "Alive" or condition == "Injured"
    end
end
local function eligible(player, forAim)
    if not state.authorized or player == LocalPlayer or not player.Parent then return false end
    local role = extraUI.adapter.role(player)
    if role == "Inactive" then return false end
    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not humanoid or humanoid.Health <= 0 or extraUI.adapter.attribute(character, "Dead") == true then return false end
    if forAim then
        if state.aimSkipDowned then
            local condition = extraUI.adapter.condition(character)
            if condition == "Knocked" or condition == "Hooked" or condition == "Carried" then return false end
        end
        local wanted = state.aimRole
        if wanted == "Auto" then
            local mine = extraUI.adapter.role(LocalPlayer)
            wanted = mine == "Killer" and "Survivor" or (mine == "Survivor" and "Killer" or "All")
        end
        if wanted ~= "All" and role ~= wanted then return false end
    else
        if not state.esp then
            if role == "Killer" and not state.espKillers then return false end
            if role == "Survivor" and not state.espSurvivors then return false end
            if role == "Unknown" then return false end
        end
    end
    if state.enemiesOnly then
        local mine = extraUI.adapter.role(LocalPlayer)
        if role ~= "Unknown" and mine ~= "Unknown" then
            if role == mine then return false end
        elseif LocalPlayer.Team and player.Team and not LocalPlayer.Neutral and not player.Neutral
            and LocalPlayer.Team == player.Team then return false end
    end
    return true
end
local function clearMarker(player)
    local marker = markers[player]
    if marker then
        marker.highlight:Destroy()
        marker.billboard:Destroy()
        markers[player] = nil
    end
end
local function markerOrigin()
    local root = characterPart(LocalPlayer.Character, "HumanoidRootPart")
    local camera = workspace.CurrentCamera
    return root and root.Position or (camera and camera.CFrame.Position)
end
local function espDistance()
    return state.lite and math.min(state.espMaxDistance, 180) or state.espMaxDistance
end
local function updateMarkers()
    local enabled = state.esp or state.espKillers or state.espSurvivors
    local origin = markerOrigin()
    for player, marker in pairs(markers) do
        if not player.Parent or not enabled or not eligible(player)
            or marker.character ~= player.Character or not marker.head.Parent
            or marker.head ~= characterPart(player.Character, "Head")
            or (origin and (marker.head.Position - origin).Magnitude > espDistance()) then clearMarker(player) end
    end
    if not enabled or not origin then return end
    for _, player in ipairs(Players:GetPlayers()) do
        if eligible(player) then
            local character = player.Character
            local head = characterPart(character, "Head")
            if head and head:IsA("BasePart") then
                local distance = (head.Position - origin).Magnitude
                if distance <= espDistance() then
                    if not markers[player] then
                        local highlight = make("Highlight", character, {Name = "VD_ClientESP",
                            Adornee = character, DepthMode = Enum.HighlightDepthMode.AlwaysOnTop,
                            FillColor = Color3.fromRGB(245, 89, 103), FillTransparency = 0.65,
                            OutlineColor = Color3.new(1, 1, 1)})
                        local billboard = make("BillboardGui", gui, {Adornee = head,
                            Size = UDim2.fromOffset(240, 44), StudsOffset = Vector3.new(0, 2.7, 0),
                            AlwaysOnTop = true, MaxDistance = 2000})
                        local text = make("TextLabel", billboard, {Size = UDim2.fromScale(1, 1),
                            BackgroundTransparency = 1, Text = "", TextColor3 = colors.text,
                            TextStrokeTransparency = 0.25, Font = Enum.Font.GothamBold, TextSize = 14, TextWrapped = true})
                        markers[player] = {character = character, head = head, highlight = highlight,
                            billboard = billboard, text = text}
                    end
                    local marker = markers[player]
                    marker.highlight.Enabled = not state.lite
                    local role = extraUI.adapter.role(player)
                    local color = role == "Killer" and Color3.fromRGB(255, 105, 120) or colors.accent
                    marker.highlight.FillColor, marker.highlight.OutlineColor, marker.text.TextColor3 = color, color, color
                    local info = role ~= "Unknown" and "[" .. role .. "]" or ""
                    if state.showPlayerState then
                        local condition = extraUI.adapter.condition(character)
                        if condition ~= "Alive" then info = info .. " [" .. condition .. "]" end
                    end
                    if state.showDistance then info = info .. (#info > 0 and " · " or "") .. string.format("%.0f stud", distance) end
                    marker.text.Text = player.DisplayName .. (#info > 0 and "\n" .. info or "")
                end
            end
        end
    end
end
connect(Players.PlayerRemoving, function(player)
    clearMarker(player)
    if extraUI.selectedTarget == player then extraUI.selectedTarget = nil; refreshUI() end
end)
local function isTyping()
    if not state.pauseTyping then return false end
    return Input:GetFocusedTextBox() ~= nil
end
-- A screen-space circle is used for both display and target selection.
local function aimRadius(camera)
    local viewport = camera.ViewportSize
    local focal = viewport.Y / (2 * math.tan(math.rad(camera.FieldOfView) / 2))
    return math.clamp(focal * math.tan(math.rad(math.min(state.aimAngle, 89))), 2,
        math.max(2, math.min(viewport.X, viewport.Y) / 2 - 6))
end
