local function aimTarget(camera)
    local manual = state.aimSelection == "Manual"
    local circle = state.aimSelection == "Auto"
    local bestPart, bestPlayer, bestScore = nil, nil, circle and aimRadius(camera) ^ 2 or math.huge
    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    rayParams.FilterDescendantsInstances = LocalPlayer.Character and {LocalPlayer.Character} or {}
    local origin = camera.CFrame.Position
    local centerX, centerY = camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2
    for _, player in ipairs(Players:GetPlayers()) do
        if (not manual or player == extraUI.selectedTarget) and eligible(player, true) then
            local target = characterPart(player.Character, state.aimPart)
            if target and target:IsA("BasePart") then
                local delta = target.Position - origin
                local projected, visible = camera:WorldToViewportPoint(target.Position)
                if (not circle or visible) and delta.Magnitude > 0.01 and delta.Magnitude <= state.aimMaxDistance then
                    local score = circle and ((projected.X - centerX) ^ 2 + (projected.Y - centerY) ^ 2) or delta.Magnitude
                    if score < bestScore then
                        local hit = state.aimWallCheck and workspace:Raycast(origin, delta, rayParams) or nil
                        if not hit or hit.Instance:IsDescendantOf(player.Character) then
                            bestScore, bestPart, bestPlayer = score, target, player
                        end
                    end
                end
            end
        end
    end
    return bestPart, bestPlayer
end
local renderName = KEY .. "_Aim"
RunService:BindToRenderStep(renderName, Enum.RenderPriority.Last.Value - 1, function(dt)
    local camera = workspace.CurrentCamera
    if not state.alive then return end
    if not camera then extraUI.circle.Visible, extraUI.guide.Visible = false, false; return end
    if not finite(dt) or dt < 0 then dt = 0 end
