    if state.rainbowText and extraUI.uiClock - (extraUI.rainbowUpdated or -1) >= (state.lite and 0.2 or 1 / 12) then
        extraUI.rainbowUpdated = extraUI.uiClock
        local offset = Vector2.new(math.sin(extraUI.uiClock * 0.8) * 0.4, 0)
        local rotation = math.sin(extraUI.uiClock * 0.4) * 15
        for _, item in ipairs(rainbowItems) do
            item.gradient.Offset, item.gradient.Rotation = offset, rotation
        end
    end
    extraUI.layoutMenu()
    extraUI.clampLogo()
    extraUI.quickScale.Scale = math.clamp(math.min((surface.X - 16) / 244, (surface.Y - 52) / (extraUI.quickHeight or 46)), 0.2, 1)
    do
        local position = extraUI.quick.Position
        local x = math.clamp(position.X.Offset, 0, math.max(0, surface.X - 244 * extraUI.quickScale.Scale))
        local y = math.clamp(position.Y.Offset, 0, math.max(0, surface.Y - (extraUI.quickHeight or 46) * extraUI.quickScale.Scale - 36))
        if x ~= position.X.Offset or y ~= position.Y.Offset then extraUI.quick.Position = UDim2.fromOffset(x, y) end
    end
    extraUI.quick.Visible = state.authorized and state.showQuick and extraUI.menuOpened == true and (minimized or not panel.Visible) and not reportPanel.Visible
    extraUI.hud.Visible = state.authorized and state.showHUD
    if not state.authorized then extraUI.circle.Visible, extraUI.guide.Visible = false, false; return end
    local paused = reportPanel.Visible or (extraUI.targetPanel and extraUI.targetPanel.Visible) or isTyping()
    inputState.pauseReason = paused and "PAUSE" or nil
    local held = inputState.right or next(inputState.held) ~= nil
    extraUI.circle.Visible = state.aim and state.showAimCircle and state.aimSelection == "Auto" and not paused
    if extraUI.circle.Visible then
        local diameter = 2 * aimRadius(camera)
        extraUI.circle.Position = UDim2.fromOffset(camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2)
        extraUI.circle.Size = UDim2.fromOffset(diameter, diameter)
    end
    local aimStatus = not state.aim and "OFF" or (paused and "PAUSED" or (state.aimHold and not held and "WAITING FOR HOLD" or "NO TARGET"))
    local trackedPart
    if state.aim and not paused and (not state.aimHold or held) then
        local humanoid = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health <= 0 then
            aimStatus = "CHARACTER NOT READY"
        elseif camera.CameraType == Enum.CameraType.Scriptable and not state.scriptableAim then
            aimStatus = "CUSTOM CAMERA BLOCKED"
        else
            local ok, target, targetPlayer = pcall(aimTarget, camera)
            extraUI.lastAimError = not ok and tostring(target) or nil
            if not ok then
                aimStatus = "ERROR (see Diagnostics)"
            elseif state.aimSelection == "Manual" and not extraUI.selectedTarget then
                aimStatus = "CHOOSE A TARGET"
            elseif target then
                trackedPart = target
                local wanted = CFrame.lookAt(camera.CFrame.Position, target.Position)
                camera.CFrame = camera.CFrame:Lerp(wanted, 1 - math.exp(-state.aimResponse * dt))
