            aimStatus, "TARGET " .. state.aimRole .. " · " .. state.aimSelection)
    end
end)

local function isGeneratorPrompt(prompt)
    local node = prompt
    for _ = 1, 8 do
        if not node or node == workspace then break end
        local name = string.lower(node.Name)
        if extraUI.adapter.tag(node, "Generator") or string.find(name, "generator", 1, true) or string.find(name, "gerador", 1, true) then
            return true
        end
        node = node.Parent
    end
    return false
end
local function promptPosition(prompt)
    local parent = prompt.Parent
    if parent and parent:IsA("Attachment") then return parent.WorldPosition end
    if parent and parent:IsA("BasePart") then return parent.Position end
    if parent and parent:IsA("Model") then return parent:GetPivot().Position end
    return nil
end
-- Map contracts recognized from the supplied references; no reference code is executed.
local function objectKind(object)
    local name = string.lower(object.Name)
    if name:match("^generator%d*$") or extraUI.adapter.tag(object, "Generator") then return "Generator" end
    if name == "pallet" or name == "palletwrong" or extraUI.adapter.tag(object, "pallet") then return "Pallet" end
    if name == "hook" or extraUI.adapter.tag(object, "HookPoint") then return "Hook" end
    if name == "gate" or name == "exitlever" or extraUI.adapter.tag(object, "Exit") or extraUI.adapter.tag(object, "gatespot") then return "Gate" end
    if string.find(name, "exit", 1, true) or string.find(name, "escape", 1, true) then return "Gate" end
    if string.find(name, "door", 1, true) then return "Door" end
    if string.find(name, "medkit", 1, true) or string.find(name, "bandage", 1, true)
        or string.find(name, "ammo", 1, true) or string.find(name, "pickup", 1, true)
        or string.find(name, "itemdrop", 1, true) then return "Item" end
    return nil
end
local function register(object)
    if object:IsA("ProximityPrompt") then prompts[object] = true end
    if not (object:IsA("Model") or object:IsA("BasePart") or object:IsA("Tool")) then return end
    local kind = objectKind(object) or (object:IsA("Tool") and "Item" or nil)
    if not kind then return end
    local target = object
    for _ = 1, 4 do
        local parent = target.Parent
        if parent and parent ~= workspace and parent:IsA("Model") and objectKind(parent) == kind then
            target = parent
        else break end
    end
    objectCandidates[target] = kind
end
local function objectAdornee(object)
    if object:IsA("BasePart") then return object end
    if object:IsA("Tool") then return object:FindFirstChild("Handle") end
    if object:IsA("Model") then
        for _, name in ipairs({"HitBox", "GeneratorBody"}) do
            local part = object:FindFirstChild(name, true)
            if part and part:IsA("BasePart") then return part end
        end
        return object.PrimaryPart or object:FindFirstChildWhichIsA("BasePart", true)
    end
    return nil
end
local function clearObjectMarker(object)
    local marker = objectMarkers[object]
    if marker then
        marker.billboard:Destroy()
        if marker.highlight then marker.highlight:Destroy() end
        objectMarkers[object] = nil
    end
end
local function inCharacter(object)
    for _, player in ipairs(Players:GetPlayers()) do
        if player.Character and object:IsDescendantOf(player.Character) then return true end
    end
    return false
end
local function updateObjectMarkers()
    if not state.authorized or not (state.objectESP or state.generatorESP or state.palletESP or state.hookESP or state.gateESP or state.itemESP) then
        for object in pairs(objectMarkers) do clearObjectMarker(object) end
        return
    end
    local origin = markerOrigin()
    if not origin then return end
    local selected, retained = {}, {}
    for object, kind in pairs(objectCandidates) do
        if object.Parent and object:IsDescendantOf(workspace) and not inCharacter(object) then
            local part = objectAdornee(object)
            if part and part:IsA("BasePart") then
                local distance = (part.Position - origin).Magnitude
                local enabled = state.objectESP or kind == "Generator" and state.generatorESP or kind == "Pallet" and state.palletESP
                    or kind == "Hook" and state.hookESP or (kind == "Gate" or kind == "Door") and state.gateESP
                    or kind == "Item" and state.itemESP
                if enabled and distance <= espDistance() then
                    table.insert(selected, {object = object, part = part, kind = kind, distance = distance})
                end
            end
        else objectCandidates[object] = nil end
    end
    table.sort(selected, function(a, b) return a.distance < b.distance end)
    for index, entry in ipairs(selected) do
        if index > (state.lite and 8 or 16) then break end
        retained[entry.object] = true
        local marker = objectMarkers[entry.object]
        if marker and marker.part ~= entry.part then clearObjectMarker(entry.object); marker = nil end
        if not marker then
            local billboard = make("BillboardGui", gui, {Adornee = entry.part,
                Size = UDim2.fromOffset(190, 34), StudsOffset = Vector3.new(0, 2, 0),
                AlwaysOnTop = true, MaxDistance = 2000})
            local text = make("TextLabel", billboard, {Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1, Text = "", TextStrokeTransparency = 0.2,
                Font = Enum.Font.GothamBold, TextSize = 14, TextColor3 = colors.accent})
            local target = entry.object:IsA("Tool") and entry.part or entry.object
            local highlight = make("Highlight", target, {Name = "VD_ObjectESP", Adornee = target,
                DepthMode = Enum.HighlightDepthMode.AlwaysOnTop, FillTransparency = 0.86, OutlineTransparency = 0.15})
            marker = {billboard = billboard, text = text, part = entry.part, highlight = highlight}
            objectMarkers[entry.object] = marker
        end
        marker.text.TextColor3 = (entry.kind == "Gate" or entry.kind == "Door") and Color3.fromRGB(249, 211, 98)
            or (entry.kind == "Hook" and Color3.fromRGB(255, 125, 150) or colors.accent)
        marker.highlight.Enabled = not state.lite
        marker.highlight.FillColor, marker.highlight.OutlineColor = marker.text.TextColor3, marker.text.TextColor3
        local text = entry.kind
        if entry.kind == "Generator" then
            local progress = extraUI.adapter.attribute(entry.object, "RepairProgress")
            if finite(progress) then text = text .. string.format(" · %.0f%%", math.clamp(progress, 0, 100)) end
        end
        marker.text.Text = text .. (state.showDistance and " · " .. string.format("%.0f stud", entry.distance) or "")
    end
    for object in pairs(objectMarkers) do if not retained[object] then clearObjectMarker(object) end end
end
clearAllVisuals = function()
    for player in pairs(markers) do clearMarker(player) end
    for object in pairs(objectMarkers) do clearObjectMarker(object) end
end
rescanObjects = function()
    objectCandidates = setmetatable({}, {__mode = "k"})
    for object in pairs(objectMarkers) do clearObjectMarker(object) end
    for _, object in ipairs(workspace:GetDescendants()) do register(object) end
    updateObjectMarkers()
    local count = 0
    for _ in pairs(objectCandidates) do count = count + 1 end
    notify("Scan complete: " .. count .. " map / item candidates.")
end
for _, object in ipairs(workspace:GetDescendants()) do register(object) end
connect(workspace.DescendantAdded, register)
for _, tag in ipairs({"Generator", "pallet", "HookPoint", "Exit", "gatespot"}) do
    pcall(function() connect(CollectionService:GetInstanceAddedSignal(tag), register) end)
end

-- BEGIN MOVEMENT CORE
local movement = {humanoid = nil, baseline = 16, restoreSpeed = nil, lastApplied = nil,
    active = false, applying = false, speedConnection = nil, parts = {}, anchors = {}}
local function restoreSpeed()
    local humanoid = movement.humanoid
    if humanoid and humanoid.Parent and movement.lastApplied ~= nil
        and math.abs(humanoid.WalkSpeed - movement.lastApplied) < 0.000001 then
        movement.applying = true
        humanoid.WalkSpeed = movement.restoreSpeed
        movement.applying = false
    end
    movement.active, movement.lastApplied, movement.restoreSpeed = false, nil, nil
end
local function restoreAnchors()
    for part, original in pairs(movement.anchors) do
        if part.Parent and part.Anchored == false then part.Anchored = original end
    end
    movement.anchors = {}
end
restoreMovement = function()
    restoreSpeed()
    restoreAnchors()
end
applyMovement = function()
    if not state.authorized then restoreMovement(); return end
    local character = LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if humanoid ~= movement.humanoid then
        if movement.speedConnection then movement.speedConnection:Disconnect(); movement.speedConnection = nil end
        restoreMovement()
        movement.humanoid, movement.parts = humanoid, {}
        movement.baseline = humanoid and humanoid.WalkSpeed > 0 and humanoid.WalkSpeed or 16
        if character then
            for _, part in ipairs(character:GetDescendants()) do
                if part:IsA("BasePart") then table.insert(movement.parts, part) end
            end
        end
        if humanoid then
            movement.speedConnection = connect(humanoid:GetPropertyChangedSignal("WalkSpeed"), function()
                if movement.applying or not state.alive then return end
                local incoming = humanoid.WalkSpeed
                if movement.active and finite(incoming) and incoming >= 0 then
                    movement.restoreSpeed = incoming
                    if state.dynamicSpeed and (not state.noSlow or incoming >= movement.baseline) then movement.baseline = incoming end
                end
                if state.authorized and (state.speedEnabled or state.noSlow) then applyMovement() end
            end)
        end
    end
    if not humanoid or humanoid.Health <= 0 then restoreMovement(); return end
    if state.speedEnabled or state.noSlow then
        if not movement.active then
            movement.restoreSpeed = humanoid.WalkSpeed
            if humanoid.WalkSpeed > 0 then movement.baseline = humanoid.WalkSpeed end
            movement.active = true
        end
        local target = movement.baseline * (state.speedEnabled and state.speedMultiplier or 1)
        if state.speedEnabled or humanoid.WalkSpeed < target then
            if humanoid.WalkSpeed ~= target then
                movement.applying = true
                humanoid.WalkSpeed = target
                movement.applying = false
            end
            movement.lastApplied = target
        end
    else
        if movement.active then restoreSpeed() end
        if humanoid.WalkSpeed > 0 then movement.baseline = humanoid.WalkSpeed end
    end
    if state.unanchor then
        for _, part in ipairs(movement.parts) do
            if part.Parent and part.Anchored then
                movement.anchors[part] = true
                part.Anchored = false
            end
        end
    elseif next(movement.anchors) then restoreAnchors() end
end
-- END MOVEMENT CORE
local localCharacterConnection
local function watchLocalCharacter(character)
    if localCharacterConnection then localCharacterConnection:Disconnect() end
    movement.parts = {}
    localCharacterConnection = connect(character.DescendantAdded, function(part)
        if part:IsA("BasePart") then table.insert(movement.parts, part) end
    end)
end
if LocalPlayer.Character then watchLocalCharacter(LocalPlayer.Character) end
connect(LocalPlayer.CharacterAdded, watchLocalCharacter)
local movementElapsed = 0
connect(RunService.Heartbeat, function(dt)
    if not state.alive then return end
    if not finite(dt) or dt < 0 then return end
    local movementActive = state.speedEnabled or state.noSlow or state.unanchor or movement.active or next(movement.anchors) ~= nil
    if movementActive then applyMovement() end
    if extraUI.updateSkillCheck then extraUI.updateSkillCheck(dt) end
    movementElapsed = movementElapsed + dt
    if movementElapsed >= 0.1 then
        movementElapsed = 0
        if not movementActive then applyMovement() end
        if os.clock() > messageUntil then
            local humanoid = movement.humanoid
            footer.Text = state.speedEnabled and string.format("Speed %.6gx · actual %.6g", state.speedMultiplier, humanoid and humanoid.WalkSpeed or 0)
                or "Ready · client controls"
        end
    end
end)

local generatorStatus = "Repair prompts OFF"
do
    local adapter = extraUI.adapter
    local skill = {check = nil, line = nil, goal = nil, attempted = false, lastAngle = nil, lastRotation = nil, lastGoal = nil, scan = 0}
    adapter.visible = function(object)
        if not object or not object.Parent then return false end
        local node = object
        for _ = 1, 20 do
            if not node or node == LocalPlayer.PlayerGui then break end
            if node:IsA("GuiObject") and not node.Visible then return false end
            if node:IsA("ScreenGui") and node.Enabled == false then return false end
            node = node.Parent
        end
        return object:IsDescendantOf(LocalPlayer.PlayerGui)
    end
    adapter.findCheck = function()
        local playerGui = LocalPlayer:FindFirstChild("PlayerGui")
        if not playerGui then return end
        for _, name in ipairs({"SkillCheckPromptGui", "SkillCheckPromptGui-con"}) do
            local root = playerGui:FindFirstChild(name)
            local check = root and (root:FindFirstChild("Check", true) or root:FindFirstChild("check", true))
            if check and check:IsA("GuiObject") then
                local line = check:FindFirstChild("Line", true) or check:FindFirstChild("line", true)
                local goal = check:FindFirstChild("Goal", true) or check:FindFirstChild("goal", true)
                if line and goal and line:IsA("GuiObject") and goal:IsA("GuiObject") then
                    if adapter.visible(check) then return check, line, goal end
                end
            end
        end
    end
    adapter.actionButton = function()
        local playerGui = LocalPlayer:FindFirstChild("PlayerGui")
        local root = playerGui and playerGui:FindFirstChild("Survivor-mob", true)
        local controls = root and root:FindFirstChild("Controls", true)
        if not controls then return end
        local button = controls:FindFirstChild("action") or controls:FindFirstChild("Gui-mob")
        if button and button:IsA("GuiButton") and adapter.visible(button) then return button end
    end
    adapter.pressCheck = function()
        extraUI.lastSkillError = nil
        local button = adapter.actionButton()
        if button and type(firesignal) == "function" then
            local downAttempted = false
            local ok, message = pcall(function()
                firesignal(button.MouseButton1Down)
                downAttempted = true
                firesignal(button.MouseButton1Up)
                firesignal(button.MouseButton1Click)
            end)
            if ok then return true, "mobile action" end
            extraUI.lastSkillError = tostring(message)
            if downAttempted then return true, "mobile action (partial input; see Diagnostics)" end
        end
        if button and type(getconnections) == "function" then
            local called = false
            for _, signal in ipairs({button.MouseButton1Down, button.MouseButton1Up, button.MouseButton1Click}) do
                local ok, listeners = pcall(getconnections, signal)
                if ok and type(listeners) == "table" then
                    for _, listener in ipairs(listeners) do
                        if type(listener.Function) == "function" then
                            local invoked = pcall(listener.Function)
                            called = called or invoked
                        end
                    end
                end
            end
            if called then return true, "mobile handler" end
        end
        if VirtualInput then
            local ok, message = pcall(function()
                VirtualInput:SendKeyEvent(true, Enum.KeyCode.Space, false, game)
                VirtualInput:SendKeyEvent(false, Enum.KeyCode.Space, false, game)
            end)
            -- If key-down worked but key-up failed, always attempt a release.
            if not ok then pcall(function() VirtualInput:SendKeyEvent(false, Enum.KeyCode.Space, false, game) end) end
            if ok then return true, "Space input" end
            extraUI.lastSkillError = tostring(message)
        end
        return false, "Action input unavailable"
    end
    extraUI.updateSkillCheck = function(dt)
        local message = "Skill check OFF"
        local paused = isTyping() or reportPanel.Visible or (extraUI.targetPanel and extraUI.targetPanel.Visible)
        local role = adapter.role(LocalPlayer)
        local humanoid = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
        if state.authorized and state.skillCheck and not paused and adapter.canRepair() then
            local ok, failure = pcall(function()
                if not extraUI.canSkillCheck then message = "Action input unavailable"; return end
                if not skill.check or not adapter.visible(skill.check) or not skill.line.Parent or not skill.goal.Parent then
                    skill.scan = skill.scan + dt
                    skill.check, skill.line, skill.goal = nil, nil, nil
                    skill.attempted, skill.lastAngle, skill.lastRotation, skill.lastGoal = false, nil, nil, nil
                    if skill.scan >= 0.1 then
                        skill.scan = 0
                        skill.check, skill.line, skill.goal = adapter.findCheck()
                    end
                end
                if not skill.check then message = "Waiting for a generator skill check"; return end
                local rotation, goalRotation = skill.line.Rotation, skill.goal.Rotation
                local angle = (rotation - goalRotation) % 360
                if not finite(angle) then message = "Invalid skill-check angle"; return end
                if (skill.lastRotation and math.abs(rotation - skill.lastRotation) > 90)
                    or (skill.lastGoal and goalRotation ~= skill.lastGoal) then
                    skill.attempted, skill.lastAngle = false, nil
                end
                local step = skill.lastAngle and ((angle - skill.lastAngle + 180) % 360 - 180) or 0
                local center = state.skillMode == "Perfect" and state.perfectAngle or state.normalAngle
                local velocity = dt > 0 and math.clamp(step / dt, -1440, 1440) or 0
                local predicted = (angle + velocity * state.skillLead) % 360
                local difference = math.abs((predicted - center + 180) % 360 - 180)
                local crossing = false
                if skill.lastAngle and math.abs(step) < 90 and step ~= 0 then
                    local toGoal = ((center - skill.lastAngle + 180) % 360 - 180)
                    crossing = step > 0 and toGoal >= 0 and toGoal <= step or step < 0 and toGoal <= 0 and toGoal >= step
                end
                extraUI.skillAngle = angle
                message = string.format("%s ARMED · %.1f°", state.skillMode, angle)
                if skill.attempted then
                    message = extraUI.skillAttempt or "Action attempted"
                elseif difference <= state.skillTolerance or crossing then
                    skill.attempted = true
                    local pressed, method = adapter.pressCheck()
                    extraUI.skillAttempt = pressed and (state.skillMode .. " action attempted · " .. method) or method
                    message = extraUI.skillAttempt
                end
                skill.lastAngle, skill.lastRotation, skill.lastGoal = angle, rotation, goalRotation
            end)
            if not ok then extraUI.lastSkillError = tostring(failure); message = "Skill check ERROR (see Diagnostics)" end
        else
            skill.lastAngle = nil
            if not state.skillCheck or not state.authorized or (not paused and not adapter.canRepair()) then
                skill.check, skill.line, skill.goal, skill.attempted, skill.lastGoal, skill.lastRotation = nil, nil, nil, false, nil, nil
            end
            if state.skillCheck then message = paused and "Skill check PAUSED" or "Waiting for a live survivor" end
        end
        extraUI.skillStatus = message
        status.Text = message .. "\n" .. (extraUI.promptStatus or generatorStatus)
    end
end
task.spawn(function()
    while state.alive do
        local ok, message = pcall(function() updateMarkers(); updateObjectMarkers() end)
        extraUI.lastESPError = not ok and tostring(message) or nil
        task.wait(state.lite and math.max(state.espRefresh, 0.65) or state.espRefresh)
    end
end)
task.spawn(function()
    while state.alive do
        if state.authorized and state.generator and extraUI.adapter.canRepair() and not isTyping() and not reportPanel.Visible and not (extraUI.targetPanel and extraUI.targetPanel.Visible) then
            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            local chosen, shortest = nil, math.huge
            local recognized = 0
            for prompt in pairs(prompts) do
                if prompt:IsDescendantOf(workspace) and isGeneratorPrompt(prompt) then
                    recognized = recognized + 1
                    local position = promptPosition(prompt)
                    if root and position and prompt.Enabled then
                        local distance = (root.Position - position).Magnitude
                        if distance <= prompt.MaxActivationDistance and distance < shortest
                            and os.clock() - (lastPrompt[prompt] or -math.huge) > 3 then
                            shortest, chosen = distance, prompt
                        end
                    end
                end
            end
            if type(firePrompt) ~= "function" then
                generatorStatus = "fireproximityprompt is unavailable."
            elseif chosen then
                lastPrompt[chosen] = os.clock()
                local ok = pcall(firePrompt, chosen)
                generatorStatus = ok and "Prompt attempted; verify progress in the game."
                    or "The executor could not trigger the prompt."
            else
                generatorStatus = recognized == 0 and "No generator prompt found; start repairing manually."
                    or "Move closer to an active generator prompt."
            end
        else
            generatorStatus = not state.generator and "Repair prompts OFF"
                or (not extraUI.adapter.canRepair() and "Repair needs a live survivor" or "Repair prompts PAUSED")
        end
        if state.alive then
            extraUI.promptStatus = generatorStatus
            status.Text = (extraUI.skillStatus or "Skill check OFF") .. "\n" .. generatorStatus
        end
        task.wait(1)
    end
end)

connect(diagnosticsButton.Activated, function()
    local lines = {"TEGRRR v0.9 diagnostics (structure only)",
        "PlaceId: " .. tostring(game.PlaceId), "GameId: " .. tostring(game.GameId),
        "fireproximityprompt: " .. tostring(type(firePrompt) == "function"),
        "fileWrite: " .. tostring(type(diskWrite) == "function"),
        "fileRead: " .. tostring(type(diskRead) == "function"),
        "EmbeddedArt: " .. tostring(brandImage ~= ""),
        "SelectedProfile: " .. profileName(),
        "Authorized: " .. tostring(state.authorized),
        "SpeedEnabled: " .. tostring(state.speedEnabled),
        "SpeedMultiplier: " .. tostring(state.speedMultiplier),
        "BaseWalkSpeed: " .. tostring(movement.baseline),
        "DynamicSpeed: " .. tostring(state.dynamicSpeed),
        "CurrentWalkSpeed: " .. tostring(movement.humanoid and movement.humanoid.WalkSpeed),
        "LocalHealth: " .. tostring(movement.humanoid and movement.humanoid.Health),
        "CameraType: " .. tostring(workspace.CurrentCamera and workspace.CurrentCamera.CameraType),
        "Aim: " .. tostring(extraUI.aimStatus or "OFF"),
        "AimHold: " .. tostring(state.aimHold),
        "AimRole: " .. state.aimRole, "AimSelection: " .. state.aimSelection,
        "AimPart: " .. state.aimPart, "WallCheck: " .. tostring(state.aimWallCheck),
        "LocalRole: " .. extraUI.adapter.role(LocalPlayer),
        "SkillCheck: " .. tostring(extraUI.skillStatus), "SkillAngle: " .. tostring(extraUI.skillAngle),
        "LastSkillError: " .. tostring(extraUI.lastSkillError),
        "AimGuide: " .. tostring(state.aimGuide),
        "GuideMode: " .. tostring(state.guideMode),
        "LineThickness: " .. tostring(state.lineThickness),
        "TeamFilter: " .. tostring(state.enemiesOnly),
        "LastESPError: " .. tostring(extraUI.lastESPError),
        "LastAimError: " .. tostring(extraUI.lastAimError),
        "ESP objects: map tags / object contracts and item names",
        "PLAYER STRUCTURE:"}
    for _, player in ipairs(Players:GetPlayers()) do
        table.insert(lines, player.Name .. " | team=" .. tostring(player.Team)
            .. " | role=" .. extraUI.adapter.role(player) .. " | state=" .. extraUI.adapter.condition(player.Character)
            .. " | neutral=" .. tostring(player.Neutral))
    end
    local keywords = {"ammo", "cooldown", "skill", "killer", "survivor", "role", "stun", "heal", "health", "damage",
        "crouch", "spear", "camera", "perk", "repair", "progress", "generator", "hook", "reload",
        "bullet", "projectile", "weapon", "gun", "aim", "shoot", "hit", "raycast"}
    local function relevant(name)
        name = string.lower(name)
        for _, keyword in ipairs(keywords) do if string.find(name, keyword, 1, true) then return true end end
        return false
    end
    local function snapshot(object)
        local ok, attributes = pcall(function() return object:GetAttributes() end)
        if ok then
            local keys = {}
            for key in pairs(attributes) do if relevant(key) then keys[#keys + 1] = key end end
            table.sort(keys)
            for index, key in ipairs(keys) do
                if index > 20 then break end
                table.insert(lines, object:GetFullName() .. " | attribute " .. key .. "=" .. string.sub(tostring(attributes[key]), 1, 160))
            end
        end
        if object:IsA("ValueBase") and relevant(object.Name) then
            table.insert(lines, object:GetFullName() .. " | " .. object.ClassName .. "=" .. string.sub(tostring(object.Value), 1, 160))
        end
    end
    table.insert(lines, "RELEVANT ATTRIBUTES / VALUES (read only; bounded):")
    snapshot(LocalPlayer)
    if LocalPlayer.Character then snapshot(LocalPlayer.Character) end
    local roots = {LocalPlayer, ReplicatedStorage}
    if LocalPlayer.Character then roots[#roots + 1] = LocalPlayer.Character end
    for _, root in ipairs(roots) do
        local matched = 0
        for _, object in ipairs(root:GetDescendants()) do
            if relevant(object.Name) or object:IsA("Tool") then
                snapshot(object)
                matched = matched + 1
                if matched >= 60 then break end
            end
        end
    end
    table.insert(lines, "PROXIMITY PROMPTS (max 80):")
    local count = 0
    for prompt in pairs(prompts) do
        if prompt:IsDescendantOf(workspace) then
            count = count + 1
            table.insert(lines, prompt:GetFullName() .. " | action=" .. prompt.ActionText
                .. " | object=" .. prompt.ObjectText .. " | generatorMatch=" .. tostring(isGeneratorPrompt(prompt)))
            if count >= 80 then break end
        end
    end
    table.insert(lines, "OBJECT MATCHES (max 60):")
    count = 0
    for object, kind in pairs(objectCandidates) do
        if object.Parent and object:IsDescendantOf(workspace) then
            count = count + 1
            table.insert(lines, kind .. " | " .. object:GetFullName())
            if count >= 60 then break end
        end
    end
    table.insert(lines, "REPLICATED REMOTE NAMES (max 80; no calls are made):")
    count = 0
    for _, object in ipairs(ReplicatedStorage:GetDescendants()) do
        if object:IsA("RemoteEvent") or object:IsA("RemoteFunction") or object:IsA("UnreliableRemoteEvent") then
            count = count + 1
            table.insert(lines, object.ClassName .. " | " .. object:GetFullName())
            if count >= 80 then break end
        end
    end
    local text = table.concat(lines, "\n")
    openModal("Game diagnostics", text, false)
    local written = type(diskWrite) == "function" and pcall(diskWrite, "VD_Tegrrr_Diagnostics.txt", text)
    local copied = type(setclipboard) == "function" and pcall(setclipboard, text)
    notify(written and "Diagnostics saved: VD_Tegrrr_Diagnostics.txt"
        or (copied and "Diagnostics copied to clipboard." or "Select and copy the diagnostics text."))
end)

local function cleanup()
    if not state.alive then return end
    state.alive = false
    restoreMovement()
    RunService:UnbindFromRenderStep(renderName)
    RunService:UnbindFromRenderStep(performanceRenderName)
    for _, connection in ipairs(connections) do connection:Disconnect() end
    for _, tween in pairs(extraUI.tweens or {}) do tween:Cancel() end
    clearAllVisuals()
    extraUI.overlay:Destroy()
    extraUI.performanceGui:Destroy()
    gui:Destroy()
    if environment[KEY] == state then environment[KEY] = nil end
end
state.cleanup = cleanup
environment[KEY] = state
